-- ----------------------------------------------------------------------------
-- HelloWhos: The smallest complete rulebook: an id, a display name, and a rule that derives a greeting from it.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS hello_whos (
  hello_who_id                        TEXT                 PRIMARY KEY
);
ALTER TABLE hello_whos ADD COLUMN IF NOT EXISTS name TEXT;
COMMENT ON TABLE hello_whos IS 'The smallest complete rulebook: an id, a display name, and a rule that derives a greeting from it.';

